DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM local_tour_stub, jsonb_array_elements(payload->'schedules') item WHERE item->>'id'='00000000-0000-0000-0000-000000000302' AND (item->>'reservedSeats')::int >= (item->>'capacity')::int) THEN
  RAISE EXCEPTION 'Demo migration needs one free place on schedule 302; cancel a local booking before upgrading';
 END IF;
END $$;
UPDATE local_tour_stub SET payload=jsonb_set(payload,'{schedules}',(SELECT jsonb_agg(CASE WHEN item->>'id'='00000000-0000-0000-0000-000000000302' THEN jsonb_set(jsonb_set(item,'{reservedSeats}',to_jsonb((item->>'reservedSeats')::int+1)),'{availableSeats}',to_jsonb((item->>'availableSeats')::int-1)) ELSE item END ORDER BY ord) FROM jsonb_array_elements(payload->'schedules') WITH ORDINALITY a(item,ord))) WHERE tour_id='00000000-0000-0000-0000-000000000201';
INSERT INTO local_tour_stub(tour_id,payload) VALUES ('00000000-0000-0000-0000-000000000205','{"id": "00000000-0000-0000-0000-000000000205", "direction": {"id": "00000000-0000-0000-0000-000000000101", "country": "Беларусь", "city": "Брест", "description": "Культурные поездки по Беларуси", "isActive": true}, "title": "История Бреста — октябрьская поездка", "description": "Завершившийся выезд для демонстрации завершения брони", "durationDays": 2, "status": "PUBLISHED", "version": 1, "createdByEmployeeId": "00000000-0000-0000-0000-000000000003", "schedules": [{"id": "00000000-0000-0000-0000-000000000307", "tourId": "00000000-0000-0000-0000-000000000205", "startsAt": "2026-10-01T05:00:00Z", "endsAt": "2026-10-03T05:00:00Z", "capacity": 10, "reservedSeats": 2, "availableSeats": 8, "price": {"amountMinor": 90000, "currency": "BYN"}, "priceVersion": 1, "version": 1, "status": "CLOSED", "accommodations": [], "transports": []}]}'::jsonb) ON CONFLICT(tour_id) DO NOTHING;
